import type * as React from 'react'

import { ButtonLink } from '@/components/button'
import {
  Hero,
  HeroActions,
  HeroContent,
  HeroDescription,
  HeroMedia,
  HeroTitle,
} from '@/components/hero'
import { IconArrowForward } from '@/icons/arrow-forward'

// ── Sample content — replace with your service's own ────────────────────────
const contentSample = {
  title: 'Built for every inbox.',
  description:
    'Reusable components, layouts and tools for NSW Government email: accessible, on-brand and proven in every major client, Outlook included.',
  actions: [
    { label: 'Get started', href: '#start' },
    { label: 'View components', href: '#components' },
  ],
}

type HeroAction = { label: string; href: string }

type HeroFramedProps = Omit<
  React.ComponentProps<typeof Hero>,
  'children' | 'content' | 'layout'
> & {
  /** Title, description and up to two actions; the first action is the primary one. */
  content?: { title: string; description: string; actions: readonly HeroAction[] }
  /** The illustration, shown as a rounded picture beside the text. */
  media: { src: string; alt: string }
}

/**
 * The quiet opener: navy title on the page's own white surface, with the
 * illustration framed as a rounded picture beside it. The default choice
 * when the hero sits under a white header and the page below is white too.
 */
export function HeroFramed({
  content = contentSample,
  media,
  color = 'white',
  labelledBy = 'hero-framed-title',
  ...props
}: HeroFramedProps) {
  const [primary, secondary] = content.actions
  const buttonColor = color === 'dark' ? 'white' : 'primary'
  return (
    <Hero color={color} layout='split' labelledBy={labelledBy} {...props}>
      <HeroContent>
        <HeroTitle id={labelledBy}>{content.title}</HeroTitle>
        <HeroDescription>{content.description}</HeroDescription>
        {primary ? (
          <HeroActions>
            <ButtonLink href={primary.href} color={buttonColor} trailingVisual={IconArrowForward}>
              {primary.label}
            </ButtonLink>
            {secondary ? (
              <ButtonLink href={secondary.href} variant='outline' color={buttonColor}>
                {secondary.label}
              </ButtonLink>
            ) : null}
          </HeroActions>
        ) : null}
      </HeroContent>
      <HeroMedia fit='framed'>
        <img src={media.src} alt={media.alt} />
      </HeroMedia>
    </Hero>
  )
}
